-- Scoped operational update. Preserve customized paragraphs, drafts and complete history.
CREATE TABLE _agency_legal_20261031(id TEXT PRIMARY KEY,previous_json TEXT NOT NULL,next_json TEXT NOT NULL);
INSERT INTO _agency_legal_20261031 SELECT id,published_json,published_json FROM legal_documents d
WHERE json_valid(published_json) AND version<'2026.10.31.1'
AND NOT EXISTS(SELECT 1 FROM json_each(d.published_json,'$.sections') s WHERE json_extract(s.value,'$.id')='agencias-titularidad')
AND NOT EXISTS(SELECT 1 FROM legal_document_versions v WHERE v.document_id=d.id AND v.version='2026.10.31.1');
UPDATE _agency_legal_20261031 SET next_json=json_set(next_json,(SELECT '$.sections['||s.key||'].blocks['||b.key||'].text' FROM json_each(next_json,'$.sections') s,json_each(s.value,'$.blocks') b WHERE json_extract(b.value,'$.text')='Una agencia solo puede vincular a una escort con autorización expresa de esa persona. La invitación debe ser aceptada por la cuenta correspondiente; está prohibido crear relaciones aparentes, reutilizar identidades o agregar personas sin consentimiento. La agencia responde por la veracidad de su información institucional y por sus propios actos, sin adquirir propiedad ni control sobre las cuentas vinculadas.' LIMIT 1),'Una agencia solo puede representar a una persona adulta con su autorización expresa y suficiente para los datos y materiales utilizados. Puede invitar a un Escort que ya tiene cuenta, cuya titular debe aceptar el vínculo y los permisos, o preparar un perfil gestionado con ID propio y sin cuenta personal vinculada, declarando la autorización de la persona representada. Ambos modos mantienen la revisión de publicación y archivos. Está prohibido crear relaciones aparentes, reutilizar identidades o agregar personas sin consentimiento. Una asociación no otorga propiedad ni acceso a la seguridad de otra cuenta.') WHERE id='terms' AND EXISTS(SELECT 1 FROM json_each(next_json,'$.sections') s,json_each(s.value,'$.blocks') b WHERE json_extract(b.value,'$.text')='Una agencia solo puede vincular a una escort con autorización expresa de esa persona. La invitación debe ser aceptada por la cuenta correspondiente; está prohibido crear relaciones aparentes, reutilizar identidades o agregar personas sin consentimiento. La agencia responde por la veracidad de su información institucional y por sus propios actos, sin adquirir propiedad ni control sobre las cuentas vinculadas.');
UPDATE _agency_legal_20261031 SET next_json=json_set(next_json,(SELECT '$.sections['||s.key||'].blocks['||b.key||'].text' FROM json_each(next_json,'$.sections') s,json_each(s.value,'$.blocks') b WHERE json_extract(b.value,'$.text')='Las categorías de visibilidad y etiquetas propias de escorts, como VIP, Premium, Bronze, MILF, Trans, Hombres o Masajes, no se aplican a agencias ni arriendos.' LIMIT 1),'Escort y Agencia pueden seleccionar VIP, Premium o Bronze según las opciones disponibles del sitio. Estas categorías no conceden verificaciones de identidad ni médicas. Las etiquetas personales como MILF, Trans, Hombres o Masajes no se trasladan al anuncio institucional de una agencia ni a un arriendo; Arriendo conserva su directorio propio.') WHERE id='terms' AND EXISTS(SELECT 1 FROM json_each(next_json,'$.sections') s,json_each(s.value,'$.blocks') b WHERE json_extract(b.value,'$.text')='Las categorías de visibilidad y etiquetas propias de escorts, como VIP, Premium, Bronze, MILF, Trans, Hombres o Masajes, no se aplican a agencias ni arriendos.');
UPDATE _agency_legal_20261031 SET next_json=json_set(next_json,(SELECT '$.sections['||s.key||'].blocks['||b.key||'].text' FROM json_each(next_json,'$.sections') s,json_each(s.value,'$.blocks') b WHERE json_extract(b.value,'$.text')='Recibimos datos directamente de la persona que visita, se registra, publica, comenta o reporta; de una agencia cuando invita a vincular un perfil, sujeto a aceptación de la escort; del funcionamiento técnico del sitio; y de proveedores que confirman entregas de correo, seguridad o funcionamiento.' LIMIT 1),'Recibimos datos directamente de la persona que visita, se registra, publica, comenta o reporta; de una agencia que invita a una titular con cuenta o que prepara un perfil gestionado con autorización expresa de la persona representada; del funcionamiento técnico del sitio; y de proveedores que confirman entregas de correo, seguridad o funcionamiento. Vincular un perfil gestionado a otra cuenta requiere aceptación de esa cuenta y comprobación manual de administración.') WHERE id='privacy' AND EXISTS(SELECT 1 FROM json_each(next_json,'$.sections') s,json_each(s.value,'$.blocks') b WHERE json_extract(b.value,'$.text')='Recibimos datos directamente de la persona que visita, se registra, publica, comenta o reporta; de una agencia cuando invita a vincular un perfil, sujeto a aceptación de la escort; del funcionamiento técnico del sitio; y de proveedores que confirman entregas de correo, seguridad o funcionamiento.');
UPDATE _agency_legal_20261031 SET next_json=json_insert(next_json,'$.sections[#]',json('{"id":"agencias-titularidad","title":"Gestión de agencias y control del anuncio","blocks":[{"id":"management-modes","type":"paragraph","text":"Una cuenta puede tener un Escort personal, agencias y arriendos. Cada agencia puede crear varios Escorts gestionados con ID propio, ligados a esa agencia mientras no se vinculen a una cuenta personal. Estos perfiles no crean cuentas ni correos ficticios, no consumen el cupo personal de quien gestiona la agencia y solo son visibles si tanto el Escort como su agencia cumplen la publicación y visibilidad requeridas. Venta solo de contenido no admite este modo de representación."},{"id":"management-consent","type":"paragraph","text":"La titular de un Escort con cuenta decide si autoriza a cada agencia a editar datos, contactos, categoría, fotos, videos, historias, visibilidad, envío a revisión, estadísticas y moderación de comentarios de ese anuncio. La consulta, carga, sustitución o retirada de documentos privados de identidad y médicos requiere autorización específica adicional, opcional y revocable. Un vínculo público por sí solo no habilita esos permisos. La agencia que aporta documentos de una persona sin cuenta debe contar con su autorización específica y facilitar su revisión por el equipo."},{"id":"management-claim","type":"paragraph","text":"La agencia puede proponer vincular un perfil gestionado al correo de una cuenta existente, activa y verificada. La propuesta vence a los siete días. Solo se completa cuando la cuenta destinataria acepta el anuncio y sus permisos, administración comprueba manualmente la titularidad y la cuenta no tiene otro Escort personal fuera de papelera. Los cambios posteriores del anuncio exigen confirmar su versión actual. Se conserva el ID, enlace, medios, reseñas y estadísticas; la cuenta destinataria pasa a ser titular y puede retirar la gestión o salir de la agencia sin perder el anuncio. La comprobación de titularidad no equivale a una verificación de identidad o médica."},{"id":"management-revocation","type":"paragraph","text":"La asociación no exige exclusividad: una titular con cuenta puede aceptar varias agencias, incluso una de su propia cuenta, y revocar los permisos por separado. Al salir conviene revisar los contactos publicados. La autorización de un anuncio no comparte contraseñas, seguridad, bandeja personal de mensajes ni biblioteca privada de toda la cuenta. Las conversaciones anteriores de la agencia permanecen en la cuenta de esa agencia. Un perfil todavía sin cuenta personal no puede quedarse sin su agencia de origen mediante una simple desvinculación."},{"id":"management-records","type":"paragraph","text":"El panel muestra invitaciones, propuestas, permisos y un historial atribuible de gestión. Se conservan registros de permisos y actividad de agencias durante 180 días y estados de avisos de correo durante 90 días, sin incorporar copias de documentos ni su contenido en esos registros. El historial de entrega de correo tiene su política propia. Los correos son avisos: no aceptan invitaciones, no transfieren titularidad y su aceptación por un proveedor no acredita lectura. Una retirada de permisos bloquea nuevas acciones de la agencia; no puede retirar copias que ya hubiese obtenido legítimamente."}]}'));
INSERT INTO legal_document_versions(id,document_id,version,document_json,published_at,published_by)
SELECT 'agency-20261031-previous-'||d.id,d.id,d.version,d.published_json,d.published_at,d.updated_by FROM legal_documents d JOIN _agency_legal_20261031 r ON r.id=d.id ON CONFLICT(document_id,version) DO NOTHING;
INSERT INTO legal_document_versions(id,document_id,version,document_json,published_at,published_by)
SELECT 'agency-20261031-current-'||id,id,'2026.10.31.1',next_json,'2026-10-31',NULL FROM _agency_legal_20261031;
UPDATE legal_documents SET published_json=(SELECT next_json FROM _agency_legal_20261031 r WHERE r.id=legal_documents.id),version='2026.10.31.1',published_at='2026-10-31',updated_at=CURRENT_TIMESTAMP,updated_by=NULL WHERE id IN(SELECT id FROM _agency_legal_20261031);
-- The existing revision trigger invalidates stale administrative editors. Never clear drafts.
DROP TABLE _agency_legal_20261031;

-- Patch only the known published rule bodies. Preserve other administrator edits.
CREATE TABLE _agency_rules_20261031(updated INTEGER NOT NULL);
INSERT INTO _agency_rules_20261031 SELECT 1 FROM site_settings,json_each(CASE WHEN json_valid(site_settings.value) THEN site_settings.value ELSE '[]' END) r WHERE site_settings.key='publication_rules' AND json_valid(site_settings.value) AND (json_extract(r.value,'$.body')='Una agencia puede invitar perfiles de escort, pero la asociación solo se mostrará después de que cada escort la acepte desde su cuenta. Una agencia no puede atribuirse la representación de otra persona sin ese consentimiento.' OR json_extract(r.value,'$.body')='Una escort puede adjuntar de forma voluntaria una imagen de carnet y/o examen médico para revisión interna. Estos archivos son privados, no se publican y solo pueden ser vistos por la persona dueña del perfil y administradores autorizados. No subas documentos de terceros.') LIMIT 1;

UPDATE site_settings SET value=json_set(value,(SELECT '$['||r.key||'].body' FROM json_each(value) r WHERE json_extract(r.value,'$.body')='Una agencia puede invitar perfiles de escort, pero la asociación solo se mostrará después de que cada escort la acepte desde su cuenta. Una agencia no puede atribuirse la representación de otra persona sin ese consentimiento.' LIMIT 1),'Una agencia puede invitar a un Escort con cuenta, que debe aceptar el vínculo y los permisos, o crear perfiles gestionados con ID propio y autorización de cada persona adulta representada. Estos últimos permanecen ligados a su agencia hasta vincularse a una cuenta existente con aceptación y comprobación administrativa. La titular con cuenta puede retirar la gestión o salir sin perder su anuncio. No se admite atribuirse representación sin consentimiento ni asociar Venta solo de contenido como Escort.'),updated_at=CURRENT_TIMESTAMP,updated_by=NULL WHERE key='publication_rules' AND json_valid(value) AND EXISTS(SELECT 1 FROM json_each(value) r WHERE json_extract(r.value,'$.body')='Una agencia puede invitar perfiles de escort, pero la asociación solo se mostrará después de que cada escort la acepte desde su cuenta. Una agencia no puede atribuirse la representación de otra persona sin ese consentimiento.');
UPDATE site_settings SET value=json_set(value,(SELECT '$['||r.key||'].body' FROM json_each(value) r WHERE json_extract(r.value,'$.body')='Una escort puede adjuntar de forma voluntaria una imagen de carnet y/o examen médico para revisión interna. Estos archivos son privados, no se publican y solo pueden ser vistos por la persona dueña del perfil y administradores autorizados. No subas documentos de terceros.' LIMIT 1),'Una escort puede adjuntar voluntariamente documentos de identidad o médicos para revisión interna. Son privados: solo su cuenta, una agencia con autorización específica para documentos y administración autorizada pueden consultarlos. El vínculo público no concede este permiso. Una agencia que aporte documentos de una persona sin cuenta debe tener su autorización específica; nunca se permite usar documentos ajenos sin autorización.'),updated_at=CURRENT_TIMESTAMP,updated_by=NULL WHERE key='publication_rules' AND json_valid(value) AND EXISTS(SELECT 1 FROM json_each(value) r WHERE json_extract(r.value,'$.body')='Una escort puede adjuntar de forma voluntaria una imagen de carnet y/o examen médico para revisión interna. Estos archivos son privados, no se publican y solo pueden ser vistos por la persona dueña del perfil y administradores autorizados. No subas documentos de terceros.');

INSERT INTO site_settings(key,value,updated_at,updated_by) SELECT 'publication_rules_updated_at','2026-10-31T12:00:00Z',CURRENT_TIMESTAMP,NULL FROM _agency_rules_20261031 WHERE true ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at,updated_by=NULL;
DROP TABLE _agency_rules_20261031;
